const svg=document.querySelector('#map'), world=document.querySelector('#world');
const NS='http://www.w3.org/2000/svg';
const project=([lon,lat])=>[(lon+112.872)*80000,(49.682-lat)*124000];
const make=(tag,attrs,parent=world)=>{const e=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);return e};
const names={118455376:['Anderson Hall',-45,-23],118456323:['Water & Environmental','Science Building',0,-38],118456334:['Hepler Hall',-45,37],118457919:['University Hall',94,0],118460063:['University Library',40,60],118460064:['University Centre','for the Arts',100,45],118467727:['Markin Hall',0,-37],118467728:['Max Bell Aquatic','Centre',-132,0],118467729:['Turcotte Hall',-130,0],118467730:["Students’ Union",60,-15],118467871:['Centre for Sport','& Wellness',-120,58],669743823:['Science Commons',0,-61],1512307261:['Community Centre','for Wellbeing',0,-35],118464081:['Kainai House',55,8],118464082:['Piikani House',-60,0],118469436:['Siksika House',-60,0],118469962:['Tsuutina House',65,0],118471957:['Residence Village',70,10]};
let box={x:0,y:0,w:1200,h:800};
function setBox(){svg.setAttribute('viewBox',`${box.x} ${box.y} ${box.w} ${box.h}`)}
function reset(){const ratio=svg.clientWidth/svg.clientHeight;let h=850,w=h*ratio;if(w<1120){w=1120;h=w/ratio}box={x:650-w/2,y:390-h/2,w,h};setBox()}
function zoom(f,cx=.5,cy=.5){const w=Math.max(250,Math.min(3500,box.w*f)),h=w*svg.clientHeight/svg.clientWidth;box={x:box.x+(box.w-w)*cx,y:box.y+(box.h-h)*cy,w,h};setBox()}
document.querySelector('#plus').onclick=()=>zoom(.8);document.querySelector('#minus').onclick=()=>zoom(1.25);document.querySelector('#reset').onclick=reset;
svg.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.12:.89,e.offsetX/svg.clientWidth,e.offsetY/svg.clientHeight)},{passive:false});
let drag=null;
svg.addEventListener('pointerdown',e=>{if(e.button!==0)return;const target=e.target.closest('[data-building]');svg.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,b:{...box},target,moved:false}});
svg.addEventListener('pointermove',e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>6)drag.moved=true;if(!drag.moved)return;box.x=drag.b.x-(e.clientX-drag.x)*box.w/svg.clientWidth;box.y=drag.b.y-(e.clientY-drag.y)*box.h/svg.clientHeight;setBox()});
svg.addEventListener('pointerup',()=>{const d=drag;drag=null;if(d&&!d.moved&&d.target)openBuilding(d.target.dataset.building)});for(const event of ['pointercancel','lostpointercapture'])svg.addEventListener(event,()=>drag=null);
svg.addEventListener('keydown',e=>{if(['+','=','-','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(e.key))e.preventDefault();if(e.key==='+'||e.key==='=')zoom(.8);if(e.key==='-')zoom(1.25);if(e.key==='Home')reset();if(e.key==='ArrowLeft')box.x-=box.w*.08;if(e.key==='ArrowRight')box.x+=box.w*.08;if(e.key==='ArrowUp')box.y-=box.h*.08;if(e.key==='ArrowDown')box.y+=box.h*.08;setBox()});
window.addEventListener('resize',reset);
(async()=>{try{const res=await fetch('campus.json');if(!res.ok)throw Error();const data=await res.json();
make('rect',{x:-2000,y:-2000,width:6000,height:6000,fill:'#edf0e6'});
for(const f of data.filter(f=>!f.tags.building&&!f.tags.highway)){const t=f.tags;if(t.natural==='water'||t.landuse==='grass'||['pitch','park','garden','recreation_ground'].includes(t.leisure))make('polygon',{points:f.points.map(project).map(p=>p.join(',')).join(' '),fill:t.natural==='water'?'#c6dad9':'#dce5ce',stroke:'none'})}
const roads=make('g',{}), buildings=make('g',{}), labels=make('g',{id:'campus-labels'});
for(const f of data.filter(f=>f.tags.highway)){const t=f.tags,points=f.points.map(project).map(p=>p.join(',')).join(' '),foot=['footway','path','pedestrian','steps'].includes(t.highway)||(t.highway==='cycleway'&&['yes','designated','permissive'].includes(t.foot));if(foot){if(['no','private'].includes(t.foot)||t.access==='private')continue;make('polyline',{points,class:'walkway-edge'},roads);make('polyline',{points,class:'walkway-surface'+((t.highway==='path'||['gravel','dirt','unpaved','ground','compacted'].includes(t.surface))?' trail':'')},roads);if(t.highway==='steps')make('polyline',{points,class:'stair-marks'},roads)}else make('polyline',{points,class:'road','stroke-width':['residential','secondary','tertiary','unclassified'].includes(t.highway)?13:6},roads)}
for(const f of data.filter(f=>f.tags.building)){const known=names[f.id];const el=make('polygon',{points:f.points.map(project).map(p=>p.join(',')).join(' '),class:'building'+(known?' main':'')},buildings);if(known){const east=['118457919','118460064','118460063','669743823'];const north=['118456323','1512307261'];const residence=['118464081','118464082','118469436','118469962','118471957'];el.classList.add(east.includes(f.id)?'east-campus':north.includes(f.id)?'north-campus':residence.includes(f.id)?'south-campus':'west-campus')}registerBuilding(el,f,known);make('title',{},el).textContent=known?known.filter(v=>typeof v==='string').join(' '):(f.tags.name||'Building');}
for(const f of data.filter(f=>names[f.id])){const a=names[f.id],lines=a.filter(v=>typeof v==='string'),dx=a[a.length-2],dy=a[a.length-1];const pts=f.points.slice(0,-1).map(project);const x=pts.reduce((s,p)=>s+p[0],0)/pts.length,y=pts.reduce((s,p)=>s+p[1],0)/pts.length;make('path',{d:`M${x},${y} L${x+dx},${y+dy}`,class:'leader'},labels);const text=make('text',{x:x+dx,y:y+dy,class:'label','data-building':f.id},labels);lines.forEach((line,i)=>make('tspan',{x:x+dx,dy:i?15:0},text).textContent=line)}
document.querySelector('#status').remove();drawFoodLabels();drawVendingLabels();loadParking();reset();
}catch(e){document.querySelector('#status').textContent='Campus map could not load. Please refresh.'}})();


const registry=new Map();let pickedRole='to',returnFocus=null;
const dialog=document.querySelector('#journey-dialog');
const codes={TH:'118467729',SA:'669743823',M:'118467727',AH:'118455376',HH:'118456334',L:'118460063',W:'118460064',WE:'118456323',SU:'118467730',EP:'1512307261',KA:'118464081',P:'118464082',SI:'118469436',TU:'118469962',PE:'118467871',RV:'118471957',A:'118457919',B:'118457919',C:'118457919',D:'118457919',E:'118457919'};
const fields=Object.fromEntries(['from','to'].map(role=>[role,{room:document.querySelector('#'+role+'-room'),building:document.querySelector('#'+role+'-building'),floor:document.querySelector('#'+role+'-floor'),hint:document.querySelector('#'+role+'-hint'),details:document.querySelector('#'+role+'-details')} ]));
function registerBuilding(el,f,known){const name=known?known.filter(v=>typeof v==='string').join(' '):(f.tags.name||'Unnamed building');registry.set(String(f.id),{name,el,points:f.points});el.dataset.building=f.id;el.setAttribute('role','button');el.setAttribute('tabindex','0');el.setAttribute('aria-label','Choose destination in '+name);for(const role of ['from','to']){const option=document.createElement('option');option.value=f.id;option.textContent=name;fields[role].building.append(option)}el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();openBuilding(f.id)}});el.addEventListener('click',e=>{if(e.detail===0)openBuilding(f.id)})}
for(const f of Object.values(fields)){const blank=document.createElement('option');blank.value='';blank.textContent='Choose building';f.building.append(blank)}
function clearResult(){document.querySelector('#journey-result').hidden=true;document.querySelector('#journey-error').textContent='';document.querySelector('#journey-text').textContent='Where are you → Where to?'}
function paint(){document.querySelectorAll('.building').forEach(e=>e.classList.remove('start','end','food'));for(const [role,f]of Object.entries(fields)){registry.get(f.building.value)?.el.classList.add(role==='from'?'start':'end')}const stop=selectedFood();if(stop)registry.get(stop.building)?.el.classList.add('food')}
function info(role){const f=fields[role],name=registry.get(f.building.value)?.name;if(name&&f.floor.value.trim())f.hint.textContent=name+' · Level '+f.floor.value.trim()+' · Please confirm against your room sign.';else f.hint.textContent=name?name+' selected. Room and floor are optional.':'Choose a building below, or enter a room code.';paint();clearResult()}
function infer(role){const f=fields[role];const raw=f.room.value.toUpperCase().replace(/[\s-]/g,'');const m=raw.match(/^([A-Z]+)([0-9]{3,4})([A-Z]?)$/);if(m&&codes[m[1]]){f.building.value=codes[m[1]];f.floor.value=m[1]==='L'&&m[2].length===4?String(Number(m[2].slice(0,2))):String(Number(m[2][0]));info(role);f.hint.textContent=registry.get(f.building.value)?.name+' · Level '+f.floor.value+' inferred from '+raw+'. Room not yet verified.'}else if(/^\d{3,4}[A-Z]?$/.test(raw)&&f.building.value){f.floor.value=f.building.value==='118460063'&&raw.replace(/[A-Z]/g,'').length===4?String(Number(raw.slice(0,2))):String(Number(raw[0]));info(role)}else{f.floor.value='';if(/[A-Z]/i.test(raw))f.building.value='';info(role);f.details.open=!!raw}}
function openPlanner(){if(!dialog.open)dialog.showModal()}
function openBuilding(id){const item=registry.get(String(id));if(!item)return;returnFocus=item.el;const f=fields[pickedRole];f.building.value=String(id);f.room.value='';f.floor.value='';info(pickedRole);f.hint.textContent=item.name+' selected. Room and floor are optional.';openPlanner();f.room.focus()}
for(const [role,f]of Object.entries(fields)){f.room.addEventListener('input',()=>infer(role));f.room.addEventListener('focus',()=>pickedRole=role);for(const input of [f.building,f.floor])input.addEventListener('input',()=>info(role));f.building.addEventListener('change',()=>info(role))}
document.querySelector('#plan').onclick=()=>{setFoodMode(false);setVendingMode(false);setParkingMode(false);openPlanner();fields.from.room.focus()};document.querySelector('#close-dialog').onclick=()=>dialog.close();dialog.addEventListener('close',()=>returnFocus?.focus());
for(const b of document.querySelectorAll('[data-pick]'))b.onclick=()=>{pickedRole=b.dataset.pick;dialog.close();document.querySelector('header .hint').textContent=pickedRole==='from'?'Select your starting building':'Select your destination building'};
document.querySelector('#swap').onclick=()=>{for(const key of ['room','building','floor']){const a=fields.from[key].value;fields.from[key].value=fields.to[key].value;fields.to[key].value=a}info('from');info('to')};



const foodStops={urban:{name:'Urban Market',building:'118457919',location:'University Hall · Level 6'},subway:{name:'Subway',building:'118457919',location:'University Hall · Level 6'},carvery:{name:'Carvery & Bakery',building:'669743823',location:'Science Commons · Level 7'},coffee:{name:'Market Coffee',building:'118460063',location:'University Library · Level 9'},tims:{name:'Tim Hortons',building:'118467871',location:'Centre for Sport & Wellness'},burrito:{name:'Burrito Loco',building:'118467871',location:'Centre for Sport & Wellness'}};
const foodEnabled=document.querySelector('#food-enabled'),foodSelect=document.querySelector('#food-stop');
function selectedFood(){return foodEnabled.checked?foodStops[foodSelect.value]:null}
foodEnabled.addEventListener('change',()=>{document.querySelector('#food-options').hidden=!foodEnabled.checked;foodSelect.disabled=!foodEnabled.checked;foodSelect.required=foodEnabled.checked;clearResult();paint()});
foodSelect.addEventListener('change',()=>{const food=selectedFood();document.querySelector('#food-info').textContent=food?food.name+' · '+food.location:'Choose a stop to include it in your journey.';clearResult();paint()});

let foodMode=false;
function drawFoodLabels(){const group=make('g',{id:'food-labels',class:'food-label-group',display:foodMode?'inline':'none'});const locations={};for(const food of Object.values(foodStops)){(locations[food.building]??=[]).push(food)}locations['118467730']=[{name:'Students’ Union Food Court',location:'Students’ Union Building'}];const offsets={'118457919':[-25,-65],'669743823':[10,-55],'118460063':[25,65],'118467871':[-125,65],'118467730':[-120,-65]};for(const [id,items]of Object.entries(locations)){const building=registry.get(id);if(!building)continue;building.el.classList.add('dining');const pts=building.points.slice(0,-1).map(project),x=pts.reduce((s,p)=>s+p[0],0)/pts.length,y=pts.reduce((s,p)=>s+p[1],0)/pts.length;const [dx,dy]=offsets[id]||[0,-35];make('path',{d:'M'+x+','+y+' L'+(x+dx)+','+(y+dy),class:'leader'},group);const text=make('text',{x:x+dx,y:y+dy,class:'label food-label'},group);items.forEach((item,i)=>make('tspan',{x:x+dx,dy:i?20:0},text).textContent=item.name);make('tspan',{x:x+dx,dy:17,class:'food-location'},text).textContent=building.name}}
function setFoodMode(on){if(on){setVendingMode(false);setParkingMode(false)}foodMode=on;svg.classList.toggle('food-view',on);document.querySelector('#food-labels')?.setAttribute('display',on?'inline':'none');document.querySelector('#food-mode').setAttribute('aria-pressed',String(on));document.querySelector('#food-mode').setAttribute('aria-label',on?'Hide food places':'Show food places');document.querySelector('header .hint').textContent=on?'Campus dining · Tap Food to restore buildings':'Select a building to choose your destination'}
document.querySelector('#food-mode').onclick=()=>setFoodMode(!foodMode);


let vendingMode=false;
function drawVendingLabels(){const group=make('g',{id:'vending-labels',class:'food-label-group',display:'none'});const places=[['118457919','University Hall','Floor / machine location unverified',-25,-75],['669743823','Science Commons','Floor / machine location unverified',0,-55],['118460063','University Library','Level 10 · near west entrance',40,75],['118467871','Sport & Wellness','Floor / machine location unverified',-125,50],['118455376','Anderson Hall','Floor / machine location unverified',-100,-40],['118467727','Markin Hall','Floor / machine location unverified',25,-30],['118467730','Students’ Union','ID card not accepted · location unverified',80,0]];for(const [id,name,detail,dx,dy]of places){const item=registry.get(id);if(!item)continue;item.el.classList.add('vending');const points=item.points.slice(0,-1).map(project),x=points.reduce((s,p)=>s+p[0],0)/points.length,y=points.reduce((s,p)=>s+p[1],0)/points.length;make('path',{d:'M'+x+','+y+' L'+(x+dx)+','+(y+dy),class:'leader'},group);const text=make('text',{x:x+dx,y:y+dy,class:'label vending-label'},group);make('tspan',{x:x+dx},text).textContent='▣ Vending · '+name;make('tspan',{x:x+dx,dy:16,class:'vending-detail'},text).textContent=detail}}
function setVendingMode(on){if(on){setFoodMode(false);setParkingMode(false)}vendingMode=on;svg.classList.toggle('vending-view',on);document.querySelector('#vending-labels')?.setAttribute('display',on?'inline':'none');document.querySelector('#vending-mode').setAttribute('aria-pressed',String(on));document.querySelector('#vending-mode').setAttribute('aria-label',on?'Hide vending locations':'Show vending locations');document.querySelector('#vending-source').hidden=!on;if(on)document.querySelector('header .hint').textContent='Vending machines · Confirmed buildings';else if(!foodMode)document.querySelector('header .hint').textContent='Select a building to choose your destination'}
document.querySelector('#vending-mode').onclick=()=>setVendingMode(!vendingMode);

let parkingMode=false,parkingPoints=[];
async function loadParking(){try{const response=await fetch('parking.json');if(!response.ok)throw Error();const lots=(await response.json()).filter(f=>f.tags.name&&f.points.length>2);const group=make('g',{id:'parking-layer',display:parkingMode?'inline':'none'});const texts=make('g',{},group),buckets={};for(const lot of lots){const p=lot.points.map(project);parkingPoints.push(...p);const poly=make('polygon',{points:p.map(p=>p.join(',')).join(' '),class:'parking-area'},group);make('title',{},poly).textContent=lot.tags.name+' · Check university parking rules';(buckets[lot.tags.name]??=[]).push(...p.slice(0,-1))}group.append(texts);for(const [name,points]of Object.entries(buckets)){const x=points.reduce((s,p)=>s+p[0],0)/points.length,y=points.reduce((s,p)=>s+p[1],0)/points.length;make('text',{x,y,class:'label parking-label'},texts).textContent='P · '+name}if(parkingMode)fitParking()}catch(e){document.querySelector('#parking-source').prepend('Parking areas could not load. Please refresh. ')}}
function fitParking(){if(!parkingPoints.length)return;const xs=parkingPoints.map(p=>p[0]),ys=parkingPoints.map(p=>p[1]),minX=Math.min(...xs)-100,maxX=Math.max(...xs)+100,minY=Math.min(...ys)-100,maxY=Math.max(...ys)+100,ratio=svg.clientWidth/svg.clientHeight;let w=maxX-minX,h=maxY-minY;if(w/h>ratio)h=w/ratio;else w=h*ratio;box={x:(minX+maxX-w)/2,y:(minY+maxY-h)/2,w,h};setBox()}
function setParkingMode(on){if(on){setFoodMode(false);setVendingMode(false)}const was=parkingMode;parkingMode=on;svg.classList.toggle('parking-view',on);document.querySelector('#parking-layer')?.setAttribute('display',on?'inline':'none');document.querySelector('#parking-mode').setAttribute('aria-pressed',String(on));document.querySelector('#parking-mode').setAttribute('aria-label',on?'Hide parking lots':'Show parking lots');document.querySelector('#parking-source').hidden=!on;if(on){document.querySelector('header .hint').textContent='Parking lots · Check signs and university parking rules';fitParking()}else if(was){reset();document.querySelector('header .hint').textContent='Select a building to choose your destination'}}
document.querySelector('#parking-mode').onclick=()=>setParkingMode(!parkingMode);
